#include "core/application/PlaybackCoordinator.hpp"
namespace airmuse { PlaybackCoordinator::PlaybackCoordinator(EventBus&e,ProviderManager&p):providers_(p),subscription_(e.Subscribe([this](const MediaEvent&ev){if(ev.kind==MediaEvent::Kind::SnapshotChanged||ev.kind==MediaEvent::Kind::SessionDiscovered)arbiter_.Observe(ev.snapshot);else if(ev.kind==MediaEvent::Kind::SessionRemoved)arbiter_.Remove(ev.providerId,ev.sessionId);})){} Result<void> PlaybackCoordinator::Dispatch(PlaybackCommand c){auto active=arbiter_.Active();if(!active)return Result<void>::Fail("no active media session");auto s=providers_.FindSession(active->providerId,active->sessionId);if(!s)return Result<void>::Fail("active session disappeared");switch(c){case PlaybackCommand::Play:return s->Play();case PlaybackCommand::Pause:return s->Pause();case PlaybackCommand::Next:return s->Next();case PlaybackCommand::Previous:return s->Previous();}return Result<void>::Fail("unknown command");} Result<void> PlaybackCoordinator::Seek(Milliseconds p){auto a=arbiter_.Active();if(!a)return Result<void>::Fail("no active media session");auto s=providers_.FindSession(a->providerId,a->sessionId);return s?s->SeekTo(p):Result<void>::Fail("active session disappeared");} }
